import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`freelance-paralegal`,heroTitle:`Build your paralegal workflow in minutes`,heroSubtitle:`Perplexity Computer helps freelance paralegals turn client needs into repeatable intake, research, drafting, and delivery workflows.`,inputUrlCta:`Build my workflow`,inputUrlPlaceholder:`your site, client brief, or job post URL`,inputUrlPrefill:`Go to {url} and build a freelance paralegal workflow around this client need. 1) Identify the practice area, target deliverables, client intake questions, jurisdiction-sensitive constraints, and required source materials. 2) Create a step-by-step workflow for intake, document collection, legal research support, drafting assistance, cite checking, quality review, and client handoff. 3) Draft reusable templates for intake forms, status updates, checklists, and delivery notes. 4) Flag tasks that require attorney review or legal advice so the workflow stays support-focused. 5) Deliver an operating playbook with tools, templates, and next steps.`,heroOverlaySteps:[`Identifying client needs, deliverables, source materials, and review boundaries`,`Mapping intake, research support, drafting, QA, and handoff steps`,`Creating reusable templates, checklists, and client update language`,`Paralegal workflow playbook and next steps ready to use`],generatingSteps:[`Visiting {url} to understand the client need, practice area, and source materials`,`Designing an agent to map intake, research support, drafting, and review steps`,`Configuring reusable templates, checklists, and delivery note generation`,`Setting up a support-focused workflow with attorney-review checkpoints`],featureSectionTitle:`From client request to repeatable legal support workflow`,featureCardTitles:[`Connects your case materials`,`Templates you can reuse`],featureCardDescriptions:[`Computer breaks the work into intake, document collection, research support, drafting, QA, and handoff steps.`,`Client briefs, firm websites, Docs, Sheets, Drive, Notion, and task trackers can all feed one organized workflow.`,`Intake forms. Matter checklists. Status updates. Delivery notes. Computer gives you a reusable operating playbook.`],capabilitySectionTitle:`Your paralegal operations assistant, on autopilot`,capabilitySectionSubtitle:`Paste a client brief or service page and get back a structured workflow with templates.`,capabilityCards:[{title:`Matter Intake Map`,description:`Computer can identify client questions, source materials, deliverables, deadlines, and attorney-review checkpoints from a brief or URL.`},{title:`Workflow Builder`,description:`Computer can map intake, document collection, research support, drafting assistance, cite checking, QA, and handoff steps.`},{title:`Template Drafting`,description:`Computer can create reusable intake forms, checklists, status updates, and delivery notes for repeat client work.`},{title:`Connect Your Tools`,description:`Computer can organize materials across Google Drive, Docs, Sheets, Notion, and task trackers.`},{title:`Remember Your Process`,description:`Computer can remember your preferred intake structure, review standards, and client communication style.`},{title:`Deadline Tracking`,description:`Computer can monitor open tasks and remind you when source materials, reviews, or client updates are due.`}]});export{t as default};
